"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["87461"],{10479(e){e.exports=JSON.parse('{"id":11050,"title":"Java \u901A\u7528\u89C4\u8303","description":"---\\nalwaysApply: true\\ndescription: Java \u9879\u76EE\u5168\u5C40\u901A\u7528\u89C4\u8303\uFF0C\u59CB\u7EC8\u751F\u6548\\n---\\n\\n# Java \u901A\u7528\u5F00\u53D1\u89C4\u5219\\n## \u57FA\u7840\u683C\u5F0F\u89C4\u8303\\n1. \u7F29\u8FDB\uFF1A\u7EDF\u4E00\u4F7F\u7528 4 \u4E2A\u7A7A\u683C\uFF0C\u7981\u6B62 Tab \u7F29\u8FDB\u3002\\n2. \u7F16\u7801\uFF1A\u6240\u6709 .java \u6587\u4EF6\u4F7F\u7528 UTF-8 \u7F16\u7801\uFF0C\u6587\u4EF6\u5934\u90E8\u6CE8\u660E `/* coding: UTF-8 */`\u3002\\n3. \u6362\u884C\uFF1A\u8BED\u53E5\u7ED3\u675F\u5FC5\u987B\u6362\u884C\uFF0C\u4E00\u884C\u53EA\u5199\u4E00\u6761\u8BED\u53E5\uFF0C\u884C\u957F\u5EA6\u4E0D\u8D85\u8FC7 120 \u5B57\u7B26\u3002\\n4. \u7A7A\u683C\uFF1A\u8FD0\u7B97\u7B26\u4E24\u4FA7\u3001\u9017\u53F7\u540E\u5FC5\u987B\u52A0\u7A7A\u683C\uFF0C\u5927\u62EC\u53F7\u524D\u540E\u52A0\u7A7A\u683C\uFF08\u5982 `if (condition) {`\uFF09\u3002\\n\\n## \u547D\u540D\u89C4\u8303\\n1. \u7C7B\u540D\uFF1APascalCase\uFF0C\u5982 `UserService`\u3001`OrderServiceImpl`\uFF0C\u5FC5\u987B\u89C1\u540D\u77E5\u610F\u3002\\n2. \u65B9\u6CD5/\u53D8\u91CF\u540D\uFF1AcamelCase\uFF0C\u5982 `getUserName()`\u3001`orderId`\uFF0C\u7981\u6B62\u62FC\u97F3+\u82F1\u6587\u6DF7\u7528\u3002\\n3. \u5E38\u91CF\u540D\uFF1AUPPER_SNAKE_CASE\uFF0C\u5982 `MAX_TIMEOUT`\u3001`DEFAULT_PAGE_SIZE`\uFF0C\u5FC5\u987B\u5168\u5927\u5199+\u4E0B\u5212\u7EBF\u3002\\n4. \u5305\u540D\uFF1A\u5168\u5C0F\u5199\uFF0C\u6309\u516C\u53F8/\u9879\u76EE\u5C42\u7EA7\u5212\u5206\uFF0C\u5982 `com.company.project.service`\u3002\\n\\n## \u8D28\u91CF\u7EA6\u675F\\n1. \u5F02\u5E38\u5904\u7406\uFF1A\u7981\u6B62\u7A7A catch \u5757\uFF0C\u5FC5\u987B\u6355\u83B7\u5177\u4F53\u5F02\u5E38\uFF08\u5982 `NullPointerException`\uFF09\uFF0C\u81EA\u5B9A\u4E49\u4E1A\u52A1\u5F02\u5E38\u7EDF\u4E00\u5C01\u88C5\u3002\\n2. \u5E9F\u5F03 API\uFF1A\u7981\u6B62\u4F7F\u7528 Date\u3001Vector \u7B49\u8FC7\u65F6 API\uFF0C\u6539\u7528 LocalDateTime\u3001ArrayList\u3002\\n3. \u65E5\u5FD7\u89C4\u8303\uFF1A\u4F7F\u7528 SLF4J + Logback\uFF0C\u7981\u6B62 System.out.println\uFF0C\u65E5\u5FD7\u5206\u7EA7\uFF08ERROR/WARN/INFO/DEBUG\uFF09\u3002\\n4. \u8D44\u6E90\u7BA1\u7406\uFF1AIO \u6D41\u3001\u6570\u636E\u5E93\u8FDE\u63A5\u3001\u7EBF\u7A0B\u6C60\u5FC5\u987B\u624B\u52A8\u5173\u95ED\u6216\u4F7F\u7528 try-with-resources \u8BED\u6CD5\u3002\\n\\n## \u7ED3\u6784\u89C4\u8303\\n1. \u9879\u76EE\u5206\u5C42\uFF1AController\uFF08\u63A7\u5236\u5C42\uFF09\u2192 Service\uFF08\u4E1A\u52A1\u5C42\uFF09\u2192 Mapper\uFF08\u6570\u636E\u5C42\uFF09\uFF0C\u5C42\u95F4\u7981\u6B62\u8DE8\u7EA7\u8C03\u7528\u3002\\n2. \u7C7B\u5927\u5C0F\uFF1A\u5355\u4E2A\u7C7B\u4EE3\u7801\u884C\u6570\u4E0D\u8D85\u8FC7 500 \u884C\uFF0C\u8D85\u8FC7\u5219\u62C6\u5206\u4E3A\u591A\u4E2A\u7C7B\u3002\\n3. \u65B9\u6CD5\u5927\u5C0F\uFF1A\u5355\u4E2A\u65B9\u6CD5\u4EE3\u7801\u884C\u6570\u4E0D\u8D85\u8FC7 50 \u884C\uFF0C\u8D85\u8FC7\u5219\u62C6\u5206\u4E3A\u5B50\u65B9\u6CD5\u3002","remark":"Trae \u4E13\u5C5E","notes":"Java \u901A\u7528\u89C4\u8303 java-general.md\\n.trae/rules \u76EE\u5F55\u4E0B\u521B\u5EFA","owner":"\u5FC3\u68A6\u65E0\u75D5","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-05-14T14:10:05.422Z"}')}}]);